/**
 * ATS-specific contract registry.
 *
 * @remarks
 * This module provides the ATS contract registry with type-safe helper
 * functions. It uses the generic registry factory from infrastructure and
 * provides the ATS-generated registry data.
 *
 * The registry data is auto-generated by `generateRegistryPipeline` from the
 * `contracts/` directory. To regenerate: `npm run generate:registry` (or any
 * `hardhat compile`).
 *
 * BBND-1766 — lazy-load contract:
 *
 * - The heavy `atsRegistry.generated.ts` (facet / contract / storage-wrapper
 *   registries, ~14k lines, auto-generated) is gitignored. It is regenerated
 *   on every `prepare` / `hardhat compile`.
 * - Bootstrap code (`hardhat.config.ts` → `tasks` → `@scripts` barrel) loads
 *   this module. To keep bootstrap working on a fresh clone — before the
 *   heavy file has been generated — every reference to `atsRegistry.generated`
 *   in this file is wrapped behind a lazy `require()`. Module load only
 *   declares closures; the data file is touched the first time a consumer
 *   actually calls a helper (e.g. `getFacetDefinition(...)`).
 * - The small `atsRoles.generated.ts` (role hashes) is checked into git for
 *   PR-diff visibility and is imported eagerly here.
 *
 * @module domain/atsRegistry
 *
 * @example
 * ```typescript
 * import {
 *     getFacetDefinition,
 *     getStorageWrapperDefinition,
 *     ROLES
 * } from '@scripts/domain'
 *
 * // Query facets
 * const facet = getFacetDefinition('AccessControlFacet')
 * console.log(facet.methods)
 *
 * // Query storage wrappers
 * const wrapper = getStorageWrapperDefinition('AccessControlStorageWrapper')
 * console.log(wrapper.methods)
 *
 * // Access roles
 * console.log(ROLES._PAUSER_ROLE)
 *
 * // Get all facets
 * const allFacets = getAllFacets()
 * const allWrappers = getAllStorageWrappers()
 * ```
 */

/**
 * @remarks
 * `import type` is fully erased at runtime — Node never tries to resolve
 * `./atsRegistry.generated` from this line. The types still flow through for
 * TypeScript autocomplete on the lazy proxies below.
 */
import type {
  FACET_REGISTRY as FACET_REGISTRY_TYPE,
  INFRASTRUCTURE_CONTRACTS as INFRASTRUCTURE_CONTRACTS_TYPE,
  STORAGE_WRAPPER_REGISTRY as STORAGE_WRAPPER_REGISTRY_TYPE,
} from "./atsRegistry.generated";

/**
 * Union of every facet contract name known to the registry.
 *
 * @remarks
 * Auto-generated alongside `FACET_REGISTRY`. Re-exported here so consumers
 * import it from `@scripts/domain` rather than reaching into the gitignored
 * generated file. The `export type` is fully erased at runtime — like the
 * `import type` above, it never resolves `./atsRegistry.generated`, so module
 * load stays bootstrap-safe.
 */
export type { FacetName } from "./atsRegistry.generated";
import type {
  FacetDefinition,
  ContractDefinition,
  StorageWrapperDefinition,
  RegistryProvider,
} from "../infrastructure";
import { createRegistryHelpers } from "../infrastructure/registryFactory";
import { getFacetRequiredLibraries } from "./orchestratorLibraries";

/**
 * @remarks
 * ROLES live in a small, audit-visible file checked into git. They are
 * imported eagerly because the file always exists on disk (never gitignored).
 */
export { ROLES } from "./atsRoles.generated";

export { getFacetRequiredLibraries, LIBRARY_DEPENDENT_FACETS } from "./orchestratorLibraries";

/**
 * Cached registry-helpers instance.
 *
 * @remarks
 * Populated by `getHelpers()` on first access. The wrapped `require()` only
 * runs once per Node process and caches via Node's CommonJS module cache.
 */
let _helpers: ReturnType<typeof createRegistryHelpers> | undefined;

/**
 * Lazy accessor for the generic registry helpers.
 *
 * @remarks
 * Loads `./atsRegistry.generated` on first invocation. Bootstrap-safe: this
 * function is never called from module top-level code in this file or its
 * importers, so the heavy data file is not touched until a consumer
 * actually queries the registry.
 *
 * @returns The configured registry-helpers singleton.
 */
function getHelpers(): ReturnType<typeof createRegistryHelpers> {
  if (!_helpers) {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const data = require("./atsRegistry.generated");
    _helpers = createRegistryHelpers(data.FACET_REGISTRY, data.INFRASTRUCTURE_CONTRACTS, data.STORAGE_WRAPPER_REGISTRY);
  }
  return _helpers;
}

/**
 * Build a transparent `Proxy` over a `Record<string, T>` that lazily
 * resolves the backing object on each operation.
 *
 * @remarks
 * Used to preserve the legacy public API for the raw registries
 * (`FACET_REGISTRY`, `INFRASTRUCTURE_CONTRACTS`, `STORAGE_WRAPPER_REGISTRY`).
 * Property access, `in` checks, `Object.keys`, and property-descriptor
 * lookups all route through the resolver. The resolver call only fires the
 * first time a consumer touches the proxy; bootstrap-time module load
 * declares the proxy without invoking the resolver.
 *
 * @param resolver - Callback returning the backing record. Invoked on every
 *                   proxy operation (cheap once the underlying `require`
 *                   has been cached by Node).
 * @returns A proxy typed as the resolver's return type.
 */
function lazyRecordProxy<T extends object>(resolver: () => T): T {
  return new Proxy({} as T, {
    get: (_target, key) => (resolver() as Record<PropertyKey, unknown>)[key as string],
    has: (_target, key) => key in (resolver() as object),
    ownKeys: () => Reflect.ownKeys(resolver()),
    getOwnPropertyDescriptor: (_target, key) => Object.getOwnPropertyDescriptor(resolver(), key),
  });
}

/**
 * Legacy raw export of the facet registry record.
 *
 * @remarks
 * Lazy proxy over `./atsRegistry.generated#FACET_REGISTRY`. Consumers should
 * prefer the typed helpers (`getFacetDefinition`, `getAllFacets`, etc.);
 * this export exists for back-compat with code that iterates the record
 * directly.
 */
export const FACET_REGISTRY: typeof FACET_REGISTRY_TYPE = lazyRecordProxy(
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  () => require("./atsRegistry.generated").FACET_REGISTRY,
);

/**
 * Legacy raw export of the infrastructure-contracts registry record.
 *
 * @remarks
 * Lazy proxy over `./atsRegistry.generated#INFRASTRUCTURE_CONTRACTS`.
 */
export const INFRASTRUCTURE_CONTRACTS: typeof INFRASTRUCTURE_CONTRACTS_TYPE = lazyRecordProxy(
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  () => require("./atsRegistry.generated").INFRASTRUCTURE_CONTRACTS,
);

/**
 * Legacy raw export of the storage-wrapper registry record.
 *
 * @remarks
 * Lazy proxy over `./atsRegistry.generated#STORAGE_WRAPPER_REGISTRY`.
 */
export const STORAGE_WRAPPER_REGISTRY: typeof STORAGE_WRAPPER_REGISTRY_TYPE = lazyRecordProxy(
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  () => require("./atsRegistry.generated").STORAGE_WRAPPER_REGISTRY,
);

/**
 * Get a facet definition by name.
 *
 * @param name - Facet name (e.g. `"AccessControlFacet"`).
 * @returns The facet definition if found, otherwise `undefined`.
 */
export function getFacetDefinition(name: string): FacetDefinition | undefined {
  return getHelpers().getFacetDefinition(name);
}

/**
 * Get an infrastructure-contract definition by name.
 *
 * @param name - Contract name (e.g. `"BusinessLogicResolver"`).
 * @returns The contract definition if found, otherwise `undefined`.
 */
export function getContractDefinition(name: string): ContractDefinition | undefined {
  return getHelpers().getContractDefinition(name);
}

/**
 * Get every facet definition in the registry.
 *
 * @returns A flat array of all known facet definitions.
 */
export function getAllFacets(): FacetDefinition[] {
  return getHelpers().getAllFacets();
}

/**
 * Get every infrastructure-contract definition in the registry.
 *
 * @returns A flat array of all known infrastructure contract definitions.
 */
export function getAllContracts(): ContractDefinition[] {
  return getHelpers().getAllContracts();
}

/**
 * Check whether a facet exists in the registry.
 *
 * @param name - Facet name to check.
 * @returns `true` when the facet is registered, otherwise `false`.
 */
export function hasFacet(name: string): boolean {
  return getHelpers().hasFacet(name);
}

/**
 * Check whether an infrastructure contract exists in the registry.
 *
 * @param name - Contract name to check.
 * @returns `true` when the contract is registered, otherwise `false`.
 */
export function hasContract(name: string): boolean {
  return getHelpers().hasContract(name);
}

/**
 * Get a storage-wrapper definition by name.
 *
 * @param name - Storage-wrapper name (e.g. `"AccessControlStorageWrapper"`).
 * @returns The storage-wrapper definition if found, otherwise `undefined`.
 */
export function getStorageWrapperDefinition(name: string): StorageWrapperDefinition | undefined {
  return getHelpers().getStorageWrapperDefinition(name);
}

/**
 * Get every storage-wrapper definition in the registry.
 *
 * @returns A flat array of all known storage-wrapper definitions.
 */
export function getAllStorageWrappers(): StorageWrapperDefinition[] {
  return getHelpers().getAllStorageWrappers();
}

/**
 * Check whether a storage wrapper exists in the registry.
 *
 * @param name - Storage-wrapper name to check.
 * @returns `true` when the wrapper is registered, otherwise `false`.
 */
export function hasStorageWrapper(name: string): boolean {
  return getHelpers().hasStorageWrapper(name);
}

/**
 * Total number of facets currently registered.
 *
 * @remarks
 * Exposed as a function so the count is computed lazily — the first call
 * triggers the underlying data load via `getHelpers()`. Previously this was
 * a plain `number` export, but a primitive cannot be lazy. Consumers should
 * call `getFacetRegistryCount()` instead of reading a top-level constant.
 *
 * @returns The number of facets in the registry.
 */
export function getFacetRegistryCount(): number {
  return getHelpers().FACET_REGISTRY_COUNT;
}

/**
 * Total number of storage wrappers currently registered.
 *
 * @remarks
 * Exposed as a function for the same lazy-load reason as
 * `getFacetRegistryCount()` above.
 *
 * @returns The number of storage wrappers in the registry.
 */
export function getStorageWrapperRegistryCount(): number {
  return getHelpers().STORAGE_WRAPPER_REGISTRY_COUNT;
}

/**
 * ATS Registry Provider.
 *
 * @remarks
 * Pre-configured registry provider implementing the `RegistryProvider`
 * interface. Use this when you need to pass a registry to infrastructure
 * operations like `registerFacets`, `registerAdditionalFacets`, or
 * `createBatchConfiguration`. The methods delegate to the lazy helpers
 * above, so module load remains bootstrap-safe.
 *
 * This is the canonical ATS registry that downstream projects should
 * combine with their custom registries using `combineRegistries()`.
 *
 * @example
 * ```typescript
 * import { atsRegistry, registerFacets } from '@hashgraph/asset-tokenization-contracts/scripts'
 *
 * await registerFacets(provider, {
 *     blrAddress,
 *     facets: deployedFacets,
 *     registries: [atsRegistry]
 * })
 * ```
 */
export const atsRegistry: RegistryProvider = {
  getFacetDefinition,
  getAllFacets,
};

/**
 * Check whether a facet requires orchestrator-library linking.
 *
 * @param facetName - Name of the facet to inspect.
 * @returns `true` when the facet declares one or more library dependencies.
 */
export function isLibraryDependentFacet(facetName: string): boolean {
  return getFacetRequiredLibraries(facetName).length > 0;
}
